		const getRoutineFolders = hevyClient.getRoutineFolders.mockImplementation(
			() => undefined,
		);
		registerHevyResources(server, createTestRuntime(hevyClient));
		const registration = getResourceRegistration(
			registerResource,
			"routine-folders",
		);

